<?php use App\Livewire\Public\MenuShow; use App\Livewire\Student\MyOrders; use App\Models\Category; use App\Models\FoodItem; use App\Models\Order; use App\Models\Stall; use App\Models\User; use Illuminate\Foundation\Testing\RefreshDatabase; use Livewire\Livewire; uses(RefreshDatabase::class); test('guests can view public food menu', function () { $this->get('/menu')->assertStatus(200)->assertSee('FOOD MENU'); }); test('students cannot access vendor or admin routes', function () { $student = User::factory()->create(['role' => 'student']); $this->actingAs($student)->get('/vendor/orders')->assertStatus(403); $this->actingAs($student)->get('/admin/dashboard')->assertStatus(403); }); test('student can place and cancel a pending order', function () { $student = User::factory()->create(['role' => 'student']); $stall = Stall::factory()->create(['status' => 'active']); $cat = Category::factory()->create(); $food = FoodItem::factory()->create(['stall_id' => $stall->id, 'category_id' => $cat->id, 'price' => 6.00, 'availability' => true]); Livewire::actingAs($student)->test(MenuShow::class, ['foodItem' => $food])->set('quantity', 2)->set('pickupTime', '01:00 PM')->call('placeOrder')->assertRedirect('/orders'); $order = Order::first(); expect((float) $order->total_amount)->toBe(12.00); Livewire::actingAs($student)->test(MyOrders::class)->call('cancelOrder', $order->id); expect($order->fresh()->status)->toBe('Cancelled'); });